import{_ as e,o as d,c as a,a6 as r}from"./chunks/framework.DfoD60a6.js";const p=JSON.parse('{"title":"WUWAOS 現行規格","description":"","frontmatter":{},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md","lastUpdated":1795598584000}'),o={name:"spec/index.md"};function h(s,t,c,n,l,i){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="wuwaos-現行規格" tabindex="-1">WUWAOS 現行規格 <a class="header-anchor" href="#wuwaos-現行規格" aria-label="Permalink to &quot;WUWAOS 現行規格&quot;">​</a></h1><p>這套規格從啟動系統開始，接著沿著 <code>read()</code> 等使用者程式操作，追蹤核心怎麼接手、何時換一條執行緒、資料從哪裡來，以及發生錯誤時如何收拾。實作以 <code>main</code> 的 <code>3a3b273</code> 為核對基準。每章列出原始碼入口和對應的驗收紀錄。</p><p>各章把恐龍書第 10 版的觀念接到 WUWAOS 的程式行為，使用原始碼、走讀例子和可重現操作說明。章末的「恐龍書與課堂筆記」收錄原筆記中的推導、算題、程式範例與其他系統案例。</p><table tabindex="0"><thead><tr><th>章</th><th>要回答的問題</th></tr></thead><tbody><tr><td><a href="./00-overview.html">00 · 專案簡介與系統架構</a></td><td>主機、QEMU、OpenSBI、核心和使用者程式各做什麼？</td></tr><tr><td><a href="./01-running.html">01 · 如何執行：啟動、建置與驗證</a></td><td>如何從原始碼或現有 Windows Release 啟動？</td></tr><tr><td><a href="./02-traps-and-syscalls.html">02 · 從使用者程式進入核心</a></td><td>系統呼叫、缺頁和中斷怎麼進核心、怎麼回去？</td></tr><tr><td><a href="./03-processes-and-threads.html">03 · 行程與執行緒</a></td><td>誰持有資源？<code>fork</code>、<code>exec</code>、<code>wait</code> 和 <code>join</code> 各做什麼？</td></tr><tr><td><a href="./04-scheduling.html">04 · 誰先跑：排程、狀態與多 Hart</a></td><td>CPU 怎麼選下一條執行緒，等待中的執行緒怎麼回來？</td></tr><tr><td><a href="./05-synchronization-problems.html">05 · 為什麼要同步</a></td><td>競爭和漏接喚醒是怎麼發生的？</td></tr><tr><td><a href="./06-synchronization-tools.html">06 · 同步工具怎麼做</a></td><td>Mutex、Semaphore 和核心等待機制各保護什麼？</td></tr><tr><td><a href="./07-io.html">07 · 資料怎麼進出：I/O 與磁碟</a></td><td><code>read()</code> 如何接到檔案、Pipe 或終端，磁碟請求怎麼完成？</td></tr><tr><td><a href="./08-virtual-memory.html">08 · 頁面、虛擬記憶體與 COW</a></td><td>位址怎麼轉譯、缺頁怎麼補、何時共享或換出頁框？</td></tr><tr><td><a href="./09-filesystem.html">09 · 資料怎麼存下來：WUFS 與磁碟復原</a></td><td>檔案如何命名、寫入，重啟時如何重播交易？</td></tr></tbody></table><p><a href="./glossary.html">名詞表</a>集中收錄正文使用的術語。原有 SPEC 的編號、網址與驗收繼續保留在<a href="./../history.html">原始規格與驗收紀錄</a>，程式檔案的分工可查<a href="./../CODE_GUIDE.html">程式碼導覽</a>。</p><p>「已實作」表示可在目前原始碼找到該行為。「已驗證」表示連結中的紀錄實際跑過該情境。「未驗證」表示仍缺少該場景的運行結果。本次整理沿用既有執行證據，重新驗證的是文件建置和連結。</p>',6)])])}const f=e(o,[["render",h]]);export{p as __pageData,f as default};
